const Veq = Ca * Va / Cb;
const Vb = Math.max(0, Math.min(2 * Veq + 1e-9, P.Vb));
function pHat(vb) {
  const nA = Ca * Va / 1000, nB = Cb * vb / 1000;
  const Vtot = (Va + vb) / 1000;
  if (Vtot <= 0) return 7;
  if (Math.abs(nA - nB) < 1e-12) return 7;
  if (nB < nA) { const Hp = (nA - nB) / Vtot; return -Math.log10(Math.max(1e-14, Hp)); }
  const OH = (nB - nA) / Vtot; return 14 + Math.log10(Math.max(1e-14, OH));
